// POST /api/setMqttSyncStatus — valida o envelope e prepara o param $1::jsonb
// para set_mqtt_sync_status(). Payload de referência: setMqttSyncStatus-payload.example.json
//
// Saída ÚNICA (return msg). O roteamento é feito por um nó Switch a jusante,
// lendo msg.payload.status:
//   - "valid"   → nó Postgres (SQL.sql)  [usa msg.params]
//   - "invalid" → http response (msg.statusCode = 400)

const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};

const intent = String(body.intent || '').toUpperCase();
let status = String(body.mqttSyncStatus || body.status || '').toLowerCase();
if (!status) {
  status = ({
    DISABLE: 'disable', FORCE_DISABLE: 'disable',
    ENABLE: 'enable',  FORCE_ENABLE: 'enable',
  })[intent] || '';
}

// QUERY é read-only e válido; os demais precisam resolver enable|disable
const isValid = (intent === 'QUERY') || status === 'enable' || status === 'disable';

if (!isValid) {
  msg.statusCode = 400;
  msg.payload = {
    status: 'invalid',
    ok: false,
    error: 'payload inválido: informe intent (DISABLE|ENABLE|FORCE_*|QUERY) ou mqttSyncStatus (enable|disable)',
    intent: intent || null,
  };
  return msg;
}

// cache em memória imediato (mantém o GET/global em sincronia). QUERY não altera.
if (status) global.set('mqttSyncStatus', status);

// param do $1::jsonb (a função deriva status/user/slave do envelope v2)
msg.params = [JSON.stringify(body)];

// marcador de roteamento p/ o Switch (o param real vai em msg.params)
msg.payload = { status: 'valid', mqttSyncStatus: status || null, intent: intent || null };

return msg;

// Desempacota o resultado do set_mqtt_sync_status() (node-red-contrib-postgresql
// devolve msg.payload como array de rows) e monta a resposta HTTP.
// Mesmo formato do API-POST-provision-format-return-response.js.

var row = null;

if (msg.payload && msg.payload[0] && msg.payload[0].result) {
  row = msg.payload[0].result;
} else if (msg.payload && msg.payload.rows && msg.payload.rows[0]) {
  row = msg.payload.rows[0].result;
}

if (!row) {
  msg.payload = { ok: false, error: 'no result' };
  msg.statusCode = 500;
} else {
  msg.payload = row;
  msg.statusCode = (row.ok === false) ? 400 : 200;
  // mantém o cache em memória coerente com o que foi persistido
  if (row.ok && row.mqttSyncStatus) {
    global.set('mqttSyncStatus', row.mqttSyncStatus);
  }
}

return msg;

// GET /api/mqttSyncStatus
// Roda DEPOIS do nó Postgres (API-GET-SYNC-getMqttSyncStatus-SQL.sql), que lê o
// status persistido em slaves.config do slave virtual "MQTT Sync".
// node-red-contrib-postgresql devolve msg.payload como array de rows.
//
// Precedência: valor do banco → cache global → 'enable' (default legado).
// O valor resolvido é gravado de volta no global (sincroniza o flow).

let fromDb = null;
if (Array.isArray(msg.payload) && msg.payload[0]) {
  fromDb = msg.payload[0].mqtt_sync_status || null;
} else if (msg.payload && msg.payload.rows && msg.payload.rows[0]) {
  fromDb = msg.payload.rows[0].mqtt_sync_status || null;
}

const mqttSyncStatus = fromDb || global.get('mqttSyncStatus') || 'enable';

// seta no flow (cache em memória)
global.set('mqttSyncStatus', mqttSyncStatus);

msg.payload = mqttSyncStatus;
msg.statusCode = 200;
return msg;
